    sessionId: context.params.sessionId,
    sessionKey: context.params.sessionKey,
  }))}`;
}

function ensureLiveSessionCapacity(key: string, context: PreparedCliRunContext): void {
  if (liveSessions.has(key) || liveSessions.size < CLAUDE_LIVE_MAX_SESSIONS) return;
  if (closeOldestIdleSession()) return;
  throw new FailoverError("Too many Claude CLI live sessions are active.", { reason: "rate_limit", ... });
}
```

#### Recommendation

Mitigate process-exhaustion by scoping and limiting live sessions more narrowly:

- **Enforce per-tenant/per-account limits** (e.g., by `agentAccountId` or authenticated principal) instead of a single global `liveSessions.size`.
- Consider adding a **hard cap per account** and a separate global cap.
- Reduce the idle timeout or make it configurable, and/or implement **LRU eviction across all sessions** (including non-idle) with safe cancellation.
- Consider requiring a server-generated, non-user-controllable session identifier for process pooling.

Example approach (sketch):
```ts
const liveSessionsByAccount = new Map<string, Map<string, ClaudeLiveSession>>();
const MAX_SESSIONS_PER_ACCOUNT = 2;

function ensureCapacity(accountId: string, key: string) {
  const pool = liveSessionsByAccount.get(accountId) ?? new Map();
  if (pool.has(key) || pool.size < MAX_SESSIONS_PER_ACCOUNT) return;
  ​// evict an idle session from *this account's pool* (LRU/oldest-idle)
  throw new FailoverError("Too many live sessions for this account", { reason: "rate_limit", ... });
}
```

</details>

<details>
<summary>2. 🟡 Race condition can spawn duplicate Claude live-session processes for same key</summary>

| Property | Value |
|----------|-------|
| **Severity** | Medium |
| **CWE** | [CWE-362](https://cwe.mitre.org/data/definitions/362.html) |
| **Location** | `src/agents/cli-runner/claude-live-session.ts:776-794` |

#### Description

`runClaudeLiveSessionTurn()` uses a shared in-memory `liveSessions` map without synchronization.

- Two concurrent calls for the same `key` can both observe `liveSessions.get(key)` as `null`.
- Both calls then `await createClaudeLiveSession(...)`, which spawns a new Claude CLI process.
- The later completion overwrites the map entry, potentially leaving the earlier spawned process orphaned (resource leak), and can result in unexpected cancellations because `replaceExistingScope: true` uses the same supervisor `scopeKey`.

This enables unbounded extra process spawns under concurrency, leading to resource exhaustion/DoS and broken session isolation semantics.

Vulnerable code:
```ts
let session = liveSessions.get(key) ?? null;
...
if (!session) {
  session = await createClaudeLiveSession({ ... });
}
```

#### Recommendation

Serialize session creation per `key`.

One approach is to store an “in-flight creation promise” (or use a per-key mutex) so only one caller creates the session, and others await it:

```ts
const liveSessionCreates = new Map<string, Promise<ClaudeLiveSession>>();

async function getOrCreateSession(key: string, create: () => Promise<ClaudeLiveSession>) {
  const existing = liveSessions.get(key);
  if (existing) return existing;

  let pending = liveSessionCreates.get(key);
  if (!pending) {
    pending = (async () => {
      try {
        const s = await create();
        liveSessions.set(key, s);
        return s;
      } finally {
        liveSessionCreates.delete(key);
      }
    })();
    liveSessionCreates.set(key, pending);
  }
  return await pending;
}
```

Additionally:
- Ensure that any superseded/orphaned session is explicitly cancelled/cleaned up.
- Consider making supervisor scope replacement deterministic by cancelling *after* the prior run is registered, or by not relying on `replaceExistingScope` for this concurrency control.

</details>

<details>
<summary>3. 🟡 System prompt passed via Claude live-session argv exposes potentially sensitive context in process listings</summary>

| Property | Value |
|----------|-------|
| **Severity** | Medium |
| **CWE** | [CWE-200](https://cwe.mitre.org/data/definitions/200.html) |
| **Location** | `src/agents/cli-runner/claude-live-session.ts:124-156` |

#### Description

In `claude-live-session` mode, the full `systemPrompt` is injected into the Claude CLI **command-line arguments** (via `backend.systemPromptArg`) when spawning a long-lived process.

Impacts:
- Command-line arguments are commonly observable by other local users/processes via `ps`, `/proc/<pid>/cmdline`, crash reports, supervisor/OS telemetry, etc.
- The spawned Claude process is kept alive and reused for up to **10 minutes idle** (`CLAUDE_LIVE_IDLE_TIMEOUT_MS`), increasing the exposure window.
- The system prompt is built from workspace/runtime context (`buildSystemPrompt` supports `contextFiles`, `skillsPrompt`, etc.), which may include sensitive data (paths, file contents, embedded secrets) depending on configuration.

Vulnerable code:
```ts
return upsertArgValue(args, backend.systemPromptArg, stripSystemPromptCacheBoundary(prompt));
```
This value then becomes part of `argv` for a persistent child process.

#### Recommendation

Avoid placing the system prompt on the command line for long-lived processes.

Recommended fixes (pick one):
1. **Send the system prompt over stdin** as a structured “system/init” message before the first user turn (preferred for live stdio mode).
2. **Use a temporary file** (like the non-live path already does with `writeCliSystemPromptFile`) and pass only the file path via argv/config:

```ts
​// spawn argv: pass file path, not prompt contents
args.push("-c", formatTomlConfigOverride("system_prompt_file", systemPromptFilePath));
```

Additional mitigations:
- Ensure any logging of spawn inputs/argv is redacted.
- Consider shortening the idle timeout or explicitly clearing/restarting the process when sensitive context is present.

</details>


